// Format Daily Digest WhatsApp Message
// Combines daily_totals, live_events, and reconciliation status

const todayStr = (() => {
  const d = new Date(Date.now() + 8 * 3600000);
  return d.toISOString().split('T')[0];
})();

// Collect data from parallel nodes
let dailyTotals = [];
let liveEvents = [];
let reconStatus = [];

try { dailyTotals = $('Fetch Daily Totals').all()[0]?.json || []; } catch(e) {}
try { liveEvents = $('Fetch Live Events').all()[0]?.json || []; } catch(e) {}
try { reconStatus = $('Fetch Reconciliation Status').all()[0]?.json || []; } catch(e) {}

if (!Array.isArray(dailyTotals)) dailyTotals = [];
if (!Array.isArray(liveEvents)) liveEvents = [];
if (!Array.isArray(reconStatus)) reconStatus = [];

// Build location totals map
const locationTotalsMap = {};
for (const row of dailyTotals) {
  const locName = row.locations?.name || row.location_id || 'Unknown';
  locationTotalsMap[row.location_id] = {
    name: locName,
    total: row.total || 0,
    cash: row.cash || 0,
    card: row.card || 0,
    sale_date: row.sale_date
  };
}

// Aggregate live events by location
const eventsByLocation = {};
for (const ev of liveEvents) {
  if (!ev.location_id) continue;
  if (!eventsByLocation[ev.location_id]) {
    eventsByLocation[ev.location_id] = { count: 0, total: 0 };
  }
  eventsByLocation[ev.location_id].count += 1;
  eventsByLocation[ev.location_id].total += (ev.amount || 0);
}

// Top performer by lead_employee across events
const empTotals = {};
for (const ev of liveEvents) {
  if (!ev.lead_employee_id) continue;
  const empName = ev.employees?.display_name || ev.lead_employee_id;
  if (!empTotals[empName]) empTotals[empName] = 0;
  empTotals[empName] += (ev.amount || 0);
}
const sortedEmployees = Object.entries(empTotals)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5);

// Sort locations by EOD total
const sortedLocations = Object.values(locationTotalsMap)
  .sort((a, b) => (b.total || 0) - (a.total || 0));

// Format currency
function formatPHP(n) {
  if (n == null) return 'N/A';
  return 'P' + Number(n).toLocaleString('en-PH', { minimumFractionDigits: 0, maximumFractionDigits: 0 });
}

// Build message
const lines = [];
lines.push(`*Daily Digest — ${todayStr}*`);
lines.push('');

if (sortedLocations.length > 0) {
  lines.push('*Top Locations (EOD Reported):*');
  for (const loc of sortedLocations) {
    lines.push(`  ${loc.name}: ${formatPHP(loc.total)} (Cash ${formatPHP(loc.cash)} / Card ${formatPHP(loc.card)})`);
  }
} else {
  lines.push('*Locations:* No EOD data received yet');
}

lines.push('');

if (sortedEmployees.length > 0) {
  lines.push('*Top Performers (Live Events):*');
  for (const [name, amt] of sortedEmployees) {
    lines.push(`  ${name}: ${formatPHP(amt)}`);
  }
} else {
  lines.push('*Performers:* No live event data');
}

lines.push('');

// Reconciliation mismatches
const reconAlerts = reconStatus.filter(r => r.status === 'alert');
const reconMissing = reconStatus.filter(r => r.status === 'missing_eod');

if (reconAlerts.length > 0) {
  lines.push('*Reconciliation Mismatches:*');
  for (const r of reconAlerts) {
    const locName = r.locations?.name || r.location_id;
    lines.push(`  MISMATCH ${locName}: diff ${r.diff_pct != null ? r.diff_pct + '%' : 'N/A'}`);
  }
  lines.push('');
}

if (reconMissing.length > 0) {
  lines.push('*Missing EODs:*');
  for (const r of reconMissing) {
    const locName = r.locations?.name || r.location_id;
    lines.push(`  NO EOD: ${locName}`);
  }
  lines.push('');
}

const totalRevenue = sortedLocations.reduce((sum, l) => sum + (l.total || 0), 0);
lines.push(`*Total Revenue Today: ${formatPHP(totalRevenue)}*`);

const message = lines.join('\n');

return [{ json: { message, todayStr, totalRevenue, locationCount: sortedLocations.length } }];
